import{G as e,W as t,n,rt as r}from"./chunks/framework.DpaCCLuo.js";import"./chunks/assets.DvAxJGtb.js";var i=JSON.parse(`{"title":"表情ごとの設定","description":"","frontmatter":{},"headers":[],"relativePath":"settings.md","filePath":"settings.md"}`),a={name:`settings.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="表情ごとの設定" tabindex="-1">表情ごとの設定 <a class="header-anchor" href="#表情ごとの設定" aria-label="Permalink to “表情ごとの設定”">​</a></h1><p>ハンドサイン（左手・右手）とFacial EX（表情メニュー）のそれぞれで、まばたき（Blink）とリップシンク（LipSync）を有効にするか選べます。チェックを外した表情の間は、その機能が止まります。</p><p><img src="/mururu-blink-lipsync/images/2.png" alt="個別設定を開いた表情ごとの設定" width="482" height="651"></p><h2 id="初期設定" tabindex="-1">初期設定 <a class="header-anchor" href="#初期設定" aria-label="Permalink to “初期設定”">​</a></h2><table tabindex="0"><thead><tr><th>入力</th><th>Blink</th><th>LipSync</th><th>理由</th></tr></thead><tbody><tr><td>Left Hand</td><td>有効</td><td>有効</td><td>ムルルの左手のハンドサインは口の表情のため、まばたきは止めない</td></tr><tr><td>Right Hand</td><td>停止</td><td>有効</td><td>ムルルの右手のハンドサインは目の表情のため、まばたきで崩れないよう止める</td></tr><tr><td>Facial EX 1〜8</td><td>停止</td><td>有効</td><td>目の表情を保つためまばたきを止める</td></tr></tbody></table><p>リップシンク用の口は話している間だけ表示されるため、リップシンクは初期設定ですべて有効です。黙っている間は表情の口がそのまま表示されます。</p><h2 id="設定を変える" tabindex="-1">設定を変える <a class="header-anchor" href="#設定を変える" aria-label="Permalink to “設定を変える”">​</a></h2><ol><li>Left Hand・Right Hand・Facial EX の行のチェックで、まとめて切り替えます。ハンドサインやFacial EXの番号ごとに変えたいときは、<strong>個別設定</strong> を開きます。</li><li><strong>設定の変更を適用</strong> を押します。押すまでアバターには反映されません。</li></ol><p>初期設定に戻すには <strong>デフォルト設定に戻す</strong> を押します。確認のあと、そのまま適用されます。</p><h2 id="止まったときの動き" tabindex="-1">止まったときの動き <a class="header-anchor" href="#止まったときの動き" aria-label="Permalink to “止まったときの動き”">​</a></h2><ul><li><strong>Blink を止めた表情</strong>: まばたきしません。目はアニメーションの表情のままになります。</li><li><strong>LipSync を止めた表情</strong>: 話していてもリップシンク用の口は表示されず、表情の口のままになります。話している途中でその表情に変えても、すぐに表情の口に戻ります。</li></ul><h2 id="詳細設定" tabindex="-1">詳細設定 <a class="header-anchor" href="#詳細設定" aria-label="Permalink to “詳細設定”">​</a></h2><h3 id="facial-exパラメータ" tabindex="-1">Facial EXパラメータ <a class="header-anchor" href="#facial-exパラメータ" aria-label="Permalink to “Facial EXパラメータ”">​</a></h3><p>Facial EXの切り替えに使っている Int 型のパラメータ名です。通常は自動で入るため、変える必要はありません。</p><p>表情メニューを改変していて自動で入らない場合は、<strong>自動検出</strong> を押すか、パラメータ名を入力してください。Expression Parameters と Modular Avatar の MA Parameters で定義したパラメータを検出できます。<code>GestureLeft</code> や <code>Voice</code> など、VRChatの組み込みパラメータは指定できません。</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};